package ru.lepli.pervyephoto;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 final ArrayList<Uri> photos=new ArrayList<>(); Bitmap logo; ImageView preview; TextView status; SeekBar size,alpha,left,top; final int PICK=101;
 public void onCreate(Bundle b){super.onCreate(b);try(InputStream in=getAssets().open("logo.png")){logo=BitmapFactory.decodeStream(in);}catch(Exception e){}
 LinearLayout root=new LinearLayout(this);root.setPadding(20,20,20,20);root.setOrientation(1);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);
 TextView title=new TextView(this);title.setText("Первые Фото");title.setTextSize(28);root.addView(title);
 status=new TextView(this);status.setText("Выберите до 10 фотографий");root.addView(status);
 Button choose=new Button(this);choose.setText("Выбрать фотографии");root.addView(choose);choose.setOnClickListener(v->pick());
 preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);root.addView(preview,new LinearLayout.LayoutParams(-1,500));
 size=slider(root,"Размер логотипа",60,20);alpha=slider(root,"Непрозрачность",100,100);left=slider(root,"Отступ слева",30,3);top=slider(root,"Отступ сверху",30,3);
 android.content.SharedPreferences prefs=getPreferences(0);size.setProgress(prefs.getInt("size",20));alpha.setProgress(prefs.getInt("alpha",100));left.setProgress(prefs.getInt("left",3));top.setProgress(prefs.getInt("top",3));
 SeekBar.OnSeekBarChangeListener listener=new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user){prefs.edit().putInt("size",size.getProgress()).putInt("alpha",alpha.getProgress()).putInt("left",left.getProgress()).putInt("top",top.getProgress()).apply();showPreview();}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}};
 for(SeekBar s:new SeekBar[]{size,alpha,left,top})s.setOnSeekBarChangeListener(listener);
 Button save=new Button(this);save.setText("Сохранить фотографии");root.addView(save);save.setOnClickListener(v->process());
 }
 SeekBar slider(LinearLayout l,String name,int max,int initial){TextView t=new TextView(this);t.setText(name);l.addView(t);SeekBar s=new SeekBar(this);s.setMax(max);s.setProgress(initial);l.addView(s);return s;}
 void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,PICK);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=PICK||result!=RESULT_OK||data==null)return;photos.clear();if(data.getClipData()!=null){for(int j=0;j<Math.min(10,data.getClipData().getItemCount());j++)photos.add(data.getClipData().getItemAt(j).getUri());}else if(data.getData()!=null)photos.add(data.getData());status.setText("Выбрано: "+photos.size());showPreview();}
 Bitmap read(Uri u,int maxSide)throws Exception{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(u)){BitmapFactory.decodeStream(in,null,o);}o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>maxSide)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap b;try(InputStream in=getContentResolver().openInputStream(u)){b=BitmapFactory.decodeStream(in,null,o);}if(b==null)throw new IOException("Не удалось открыть фото");return orient(u,b);}
 Bitmap orient(Uri u,Bitmap b){try(InputStream in=getContentResolver().openInputStream(u)){android.media.ExifInterface ex=new android.media.ExifInterface(in);int orientation=ex.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix m=new Matrix();switch(orientation){case 3:m.postRotate(180);break;case 6:m.postRotate(90);break;case 8:m.postRotate(270);break;case 2:m.postScale(-1,1);break;case 4:m.postScale(1,-1);break;case 5:m.postRotate(90);m.postScale(-1,1);break;case 7:m.postRotate(270);m.postScale(-1,1);break;default:return b;}Bitmap rotated=Bitmap.createBitmap(b,0,0,b.getWidth(),b.getHeight(),m,true);if(rotated!=b)b.recycle();return rotated;}catch(Exception e){return b;}}
 Bitmap overlay(Bitmap b){Bitmap out=b.copy(Bitmap.Config.ARGB_8888,true);if(logo==null)return out;float target=Math.min(out.getWidth(),out.getHeight())*Math.max(5,size.getProgress())/100f;float scale=target/Math.max(logo.getWidth(),logo.getHeight());float x=out.getWidth()*left.getProgress()/100f,y=out.getHeight()*top.getProgress()/100f;Paint p=new Paint(3);p.setFilterBitmap(true);p.setAlpha(alpha.getProgress()*255/100);new Canvas(out).drawBitmap(logo,null,new RectF(x,y,x+logo.getWidth()*scale,y+logo.getHeight()*scale),p);return out;}
 void showPreview(){if(photos.isEmpty())return;try{Bitmap b=read(photos.get(0),1100);Bitmap o=overlay(b);preview.setImageBitmap(o);b.recycle();}catch(Exception e){status.setText("Ошибка просмотра: "+e.getMessage());}}
 void process(){if(photos.isEmpty()){Toast.makeText(this,"Сначала выберите фото",0).show();return;}status.setText("Обработка...");new Thread(()->{int ok=0;String error="";for(Uri u:photos){Bitmap b=null,out=null;try{b=read(u,6000);out=overlay(b);String mime=getContentResolver().getType(u);boolean png="image/png".equals(mime);String ext=png?"png":"jpg";ContentValues cv=new ContentValues();cv.put(MediaStore.Images.Media.DISPLAY_NAME,"Pervye_"+System.currentTimeMillis()+"_"+ok+"."+ext);cv.put(MediaStore.Images.Media.MIME_TYPE,png?"image/png":"image/jpeg");cv.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/PervyePhoto");cv.put(MediaStore.Images.Media.IS_PENDING,1);Uri dest=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,cv);if(dest==null)throw new IOException("Нет доступа к галерее");try(OutputStream stream=getContentResolver().openOutputStream(dest)){if(stream==null||!out.compress(png?Bitmap.CompressFormat.PNG:Bitmap.CompressFormat.JPEG,95,stream))throw new IOException("Ошибка записи");}catch(Exception e){getContentResolver().delete(dest,null,null);throw e;}cv.clear();cv.put(MediaStore.Images.Media.IS_PENDING,0);getContentResolver().update(dest,cv,null,null);ok++;}catch(Exception e){error=e.getMessage();}finally{if(out!=null)out.recycle();if(b!=null)b.recycle();}}final int count=ok;final String err=error;runOnUiThread(()->status.setText("Сохранено "+count+" из "+photos.size()+" в Pictures/PervyePhoto"+(err.isEmpty()?"":"; ошибка: "+err)));}).start();}
}